import json, subprocess, sys
def run(raw, label):
    p = subprocess.run([sys.executable,'-I','submission/main.py'],input=raw,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    try: out=json.loads(p.stdout)
    except Exception: out={'RAW':p.stdout[:120]}
    print('%-28s rc=%d out=%s' % (label, p.returncode, str(out)[:150]))
    if p.stderr: print('   stderr:', p.stderr[:200])
base = {'version':1,'ixps':[],'rib':[{'path':[1,2,3],'count':1},{'path':[2,3,1],'count':1},{'path':[3,1,2],'count':1}],'priors':[],'declared':[],'order':[[1,2],[1,3],[2,3]],'queries':[]}
run(json.dumps(base).encode()+b'\n\n  ', 'trailing whitespace')
run(b'\xef\xbb\xbf'+json.dumps(base).encode(), 'utf8 BOM')
run(b'[' * 2000 + b']' * 2000, 'deep nesting')
run(json.dumps(base).encode().replace(b'[1,2,3]', b'[1,2,3]')*200000, 'huge input')
run(json.dumps({'version':1,'ixps':[],'rib':[],'priors':[],'declared':[],'order':[],'queries':[{'id':'q','path':[1,1,1],'threshold':[1,2]}]}).encode(), 'query all same asn')
